/**
 * Normalize project path to Claude Code format
 *
 * Windows:  D:\Projects\MyProject -> d-projects-myproject
 * Linux/Mac: /home/user/projects/my-project -> home-user-projects-my-project
 */
function normalizeProjectPath(projectPath: string): string {
    // Normalize path separators and convert to lowercase
    let normalized = projectPath
        .replace(/\\/g, '/')  // Convert all backslashes to forward slashes
        .toLowerCase();

    // Remove Windows drive letter colon (e.g., "d:" -> "d")
    normalized = normalized.replace(/^([a-z]):/, '$1');

    // Split by path separator and filter out empty parts
    const parts = normalized.split('/').filter(part => part.length > 0);

    // Join with dashes
    return parts.join('-');
}

